<script setup>
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { useQuasar } from 'quasar'
import { http, unwrap, errorMessage } from '../services/http.js'
const props=defineProps({ modelValue:{type:Array,default:()=>[]} }),emit=defineEmits(['update:modelValue'])
const $q=useQuasar(),items=ref([]),dialog=ref(false),loading=ref(false)
let field, start, end
function focus(event){const el=event.target;if(el.closest('.template-dialog')&&el.matches('textarea,input[type="text"],input[type="url"],input:not([type])')){field=el}}
onMounted(()=>document.addEventListener('focusin',focus));onBeforeUnmount(()=>document.removeEventListener('focusin',focus))
async function open(){start=field?.selectionStart;end=field?.selectionEnd;dialog.value=true;loading.value=true;try{items.value=unwrap(await http.get('/site-templates')).items}catch(cause){$q.notify({type:'negative',message:errorMessage(cause)})}finally{loading.value=false}}
function insert(item){if(!props.modelValue.includes(item.id)){if(props.modelValue.length>=20){$q.notify({type:'warning',message:'Vincule até 20 sites por template.'});return}emit('update:modelValue',[...props.modelValue,item.id])}if(field?.isConnected&&!field.readOnly){field.value=field.value.slice(0,start??field.value.length)+item.url+field.value.slice(end??field.value.length);field.dispatchEvent(new Event('input',{bubbles:true}));field.focus()}else navigator.clipboard?.writeText(item.url).then(()=>$q.notify({type:'positive',message:'Link copiado. Cole no texto ou variável desejada.'})).catch(()=>{});dialog.value=false}
</script>
<template><div class="site-link-picker"><q-btn outline no-caps dense color="purple" icon="public" label="Inserir link de site" @mousedown.prevent @click="open"/><span>Selecione antes o campo de texto ou a variável que receberá o link.</span><q-chip v-for="id in modelValue" :key="id" removable dense color="purple-1" text-color="purple" icon="public" @remove="emit('update:modelValue',modelValue.filter(value=>value!==id))">{{items.find(item=>item.id===id)?.name || 'Site vinculado'}}</q-chip><q-dialog v-model="dialog"><q-card class="site-link-dialog"><q-card-section class="row items-center"><strong class="col">Sites de notificação</strong><q-btn flat round icon="close" v-close-popup/></q-card-section><q-list separator><q-item v-for="item in items" :key="item.id" clickable @click="insert(item)"><q-item-section avatar><q-icon name="public" color="purple"/></q-item-section><q-item-section><q-item-label>{{item.name}}</q-item-label><q-item-label caption>{{item.visibility==='private'?'Privado':'Público'}} · {{item.url}}</q-item-label></q-item-section><q-item-section side><q-icon name="add_link" color="purple"/></q-item-section></q-item></q-list><q-card-section v-if="!items.length">{{loading?'Carregando…':'Cadastre um site na aba Site para inserir seu link aqui.'}}</q-card-section></q-card></q-dialog></div></template>
<style scoped>.site-link-picker{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:14px}.site-link-picker>span{font-size:11px;color:#7a6c87}.site-link-dialog{width:600px;max-width:94vw;border-radius:18px}</style>
